INSERT INTO dtb_base_info (id, shop_name, shop_kana, shop_name_eng, company_name, postal_code, pref_id, addr01, addr02, phone_number, business_hour, email01, message, create_date, update_date, discriminator_type)
VALUES (1, JSON_VALUE(:entity, '$.shopName'), JSON_VALUE(:entity, '$.shopKana'), JSON_VALUE(:entity, '$.shopNameEng'), JSON_VALUE(:entity, '$.companyName'), JSON_VALUE(:entity, '$.postalCode'), CAST(JSON_VALUE(:entity, '$.pref') AS UNSIGNED), JSON_VALUE(:entity, '$.addr01'), JSON_VALUE(:entity, '$.addr02'), JSON_VALUE(:entity, '$.phoneNumber'), JSON_VALUE(:entity, '$.businessHour'), JSON_VALUE(:entity, '$.shopEmail01'), JSON_VALUE(:entity, '$.shopMessage'), NOW(), NOW(), 'baseinfo')
ON DUPLICATE KEY UPDATE shop_name=VALUES(shop_name), shop_kana=VALUES(shop_kana), shop_name_eng=VALUES(shop_name_eng), company_name=VALUES(company_name), postal_code=VALUES(postal_code), pref_id=VALUES(pref_id), addr01=VALUES(addr01), addr02=VALUES(addr02), phone_number=VALUES(phone_number), business_hour=VALUES(business_hour), email01=VALUES(email01), message=VALUES(message), update_date=NOW()
